/* Group Block Request list, Figma 178:7525. Scoped to this screen. */
(()=>{
const samples=[["GBR-007","Diego Alvarez","10/16/2026","10/18/2026","08/25/2026","Conference","$190.00","$140.00","26","Converted"],["GBR-006","Ruth Okoye","10/02/2026","10/04/2026","08/12/2026","Day of reflection","$165.00","$95.00","10","Converted"],["GBR-005","Paul Dubois","09/18/2026","09/20/2026","07/29/2026","Retreat","$190.00","$140.00","12","Converted"],["GBR-004","Mina Sato","09/04/2026","09/06/2026","07/15/2026","Family Day","$150.00","$100.00","22","Converted"],["GBR-003","Victor Hale","08/27/2026","08/29/2026","07/01/2026","Youth camp","$150.00","$110.00","9","Converted"],["GBR-002","Hannah Cole","08/13/2026","08/15/2026","06/18/2026","Wellness retreat","$210.00","$140.00","14","Confirmed"],["GBR-001","Lena Fischer","07/24/2026","07/26/2026","06/03/2026","Team retreat","$210.00","$150.00","18","Converted"]];
let view='All Requests',sortColumn=4,ascending=false,selected=new Set(),search='',pinned=true;
const labels=['Name','Contact','Start Date','End Date','Created Date','Group Type','Maximum Room Rate','Minimum Room Rate','Number of rooms','Status'];
const widths=[40,100,163,120,120,160,163,110,110,110,100,50];
const shortDate=s=>s?s.slice(5,7)+'/'+s.slice(8,10)+'/'+s.slice(0,4):'';
function records(){const r=state.request;let rows=samples.map(x=>x.slice());if(r)rows.unshift(['GBR-008',name(r),shortDate(r.start),shortDate(r.end),shortDate(r.createdDate||'2026-09-08'),r.type,money(r.maximumRate||190),money(r.minimumRate||140),String(requestedRoomCount(r)),r.status]);return rows.filter(x=>(view==='All Requests'||x[9]===view)&&x.join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>{let x=a[sortColumn],y=b[sortColumn];if([2,3,4].includes(sortColumn)){x=Date.parse(x);y=Date.parse(y);}else if([6,7,8].includes(sortColumn)){x=Number(x.replace(/[$,]/g,''));y=Number(y.replace(/[$,]/g,''));}return (typeof x==='number'?x-y:x.localeCompare(y))*(ascending?1:-1);});}
function icon(file,label,action,drop=false){return `<button type="button" class="request-icon" aria-label="${label}" title="${label}" data-action="${action}">${img(file)}${drop?img('5b518.svg','','request-dropdown'):''}</button>`;}
adminList=function(){const rows=records();return `<div class="admin request-list-page">${sfNav()}<header class="request-list-header"><div class="row">${img('dc129.svg','','request-list-logo')}<div><small>Group Block Requests</small><div class="request-view-row"><button class="request-view" data-action="rl-views">${esc(view)}${img('a62c3.svg')}</button>${icon('464b0.svg',pinned?'Unpin this list':'Pin this list','rl-pin')}</div></div></div><div class="request-button-group">${button('New','new-request')}${button('Assign Label','rl-label')}</div></header><div class="list-meta">${rows.length} items · Sorted by ${labels[sortColumn]} · Updated a few seconds ago</div><div class="admin-main"><section class="panel list-table"><div class="list-toolbar"><label class="request-list-search">${img('cd2f1.svg')}<input type="search" name="list-search" aria-label="Search this list" placeholder="Search this list..." value="${esc(search)}"></label>${icon('ba5eb.svg','List view controls','rl-controls',true)}${icon('e1fef.svg','Display as','rl-display',true)}${icon('6bf8a.svg','Refresh','rl-refresh')}${icon('c03bf.svg',ascending?'Sort descending':'Sort ascending','rl-direction')}${icon('16012.svg','Edit list','rl-edit')}${icon('709bd.svg','Show charts','rl-charts')}${icon('3f6d7.svg','Filter list','rl-filter')}</div><div class="table-wrap"><table id="request-list"><colgroup>${widths.map(w=>`<col style="width:${w}px">`).join('')}</colgroup><thead><tr><th><input type="checkbox" aria-label="Select all requests" data-rl-select-all ${rows.length&&rows.every(r=>selected.has(r[0]))?'checked':''}></th>${labels.map((l,i)=>`<th aria-sort="${sortColumn===i?(ascending?'ascending':'descending'):'none'}"><button class="request-column" data-action="rl-sort-${i}" title="${l}"><span>${l}</span>${sortColumn===i?img('3174f.svg','','request-sort '+(ascending?'is-ascending':'')):''}${img('c90a4.svg','','request-column-chevron')}</button></th>`).join('')}<th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-search="${esc(r.join(' ').toLowerCase())}" ${selected.has(r[0])?'class="selected"':''}><td><input type="checkbox" aria-label="Select ${r[0]}" data-rl-select="${r[0]}" ${selected.has(r[0])?'checked':''}></td>${r.map((v,j)=>`<td title="${esc(v)}">${j<2?button(esc(v),r[0]==='GBR-008'?(j===0?'open-request':'contact'):'rl-record-'+r[0],'link'):esc(v)}</td>`).join('')}<td>${icon('87a19.svg','Actions for '+r[0],'rl-actions-'+r[0])}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">No requests match your search.</div>'}</section></div></div>`;};
const priorOverlay=renderOverlay,priorHandle=handle;
function dialog(title,body,footer=''){document.body.style.overflow='hidden';$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal small" role="dialog" aria-modal="true" aria-labelledby="rl-title"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><header class="modal-header" id="rl-title">${title}</header><div class="modal-content stack">${body}</div><footer class="modal-footer">${button('Close','close-modal')}${footer}</footer></section></div>`;}
renderOverlay=function(){if(!modal?.startsWith('rl-'))return priorOverlay();if(modal==='rl-views'||modal==='rl-filter')return dialog('Request views',['All Requests','Pending','Confirmed','Converted'].map(v=>button(v,'rl-view-'+v)).join(''));if(modal==='rl-label')return dialog('Assign label',selected.size?`<p>${selected.size} requests selected</p><label class="field">Label<input name="rl-label-name" value="Retreat booking"></label>`:'<p>Select one or more requests to assign a label.</p>',selected.size?button('Save','rl-save-label','primary'):'');if(modal.startsWith('rl-actions-')){const id=modal.slice(11);return dialog(id,button('View request',id==='GBR-008'?'open-request':'rl-record-'+id));}if(modal.startsWith('rl-record-')){const r=samples.find(r=>r[0]===modal.slice(10));return dialog(r[0],r.map((v,i)=>detail(labels[i],esc(v))).join(''));}if(modal==='rl-charts'){const rows=records();return dialog('Requests by status',['Pending','Confirmed','Converted'].map(s=>line(s,rows.filter(r=>r[9]===s).length)).join(''));}if(modal==='rl-display')return dialog('Display as',button('Table','close-modal'));return dialog('List view controls',button('All Requests','rl-view-All Requests')+button('Sort by Created Date','rl-sort-4'));};
handle=function(a,el){if(!a.startsWith('rl-'))return priorHandle(a,el);if(a.startsWith('rl-sort-')){const col=Number(a.slice(8));ascending=col===sortColumn?!ascending:false;sortColumn=col;modal=null;render();return;}if(a==='rl-direction'){ascending=!ascending;render();return;}if(a==='rl-pin'){pinned=!pinned;render();return;}if(a==='rl-refresh'){render();return;}if(a.startsWith('rl-view-')){view=a.slice(8);modal=null;render();return;}if(a==='rl-save-label'){const label=$('[name="rl-label-name"]').value.trim();if(!label)return;state.ui.requestLabels??={};for(const id of selected)state.ui.requestLabels[id]=label;save();modal=null;render();toast('Label assigned.');return;}modal=a;renderOverlay();};
document.addEventListener('input',e=>{if(e.target.name==='list-search'&&e.target.closest('.request-list-page'))search=e.target.value;});
document.addEventListener('change',e=>{if(e.target.matches('[data-rl-select]')){e.target.checked?selected.add(e.target.dataset.rlSelect):selected.delete(e.target.dataset.rlSelect);e.target.closest('tr').classList.toggle('selected',e.target.checked);}if(e.target.matches('[data-rl-select-all]')){for(const r of records())e.target.checked?selected.add(r[0]):selected.delete(r[0]);render();}});
render();
})();
